// --- Read directly from upstream Code node output (no webhook/.body anymore) ---
const item = $input.first().json;

// --- Recursively collect all {topic, keywords} objects, wherever they live ---
function collectExtractedInfo(obj) {
  let results = [];
  if (Array.isArray(obj)) {
    for (const o of obj) results.push(...collectExtractedInfo(o));
    return results;
  }
  if (obj && typeof obj === 'object') {
    if (Array.isArray(obj.extracted_information)) {
      for (const ei of obj.extracted_information) {
        if (ei && typeof ei === 'object') results.push(ei);
      }
    }
    for (const key of Object.keys(obj)) {
      if (/^block_\d+_output$/.test(key) && obj[key] && typeof obj[key] === 'object') {
        results.push(...collectExtractedInfo(obj[key]));
      }
    }
  }
  return results;
}

const infoList = collectExtractedInfo(item);

// --- Fallback: maybe topic/keywords sit directly on the root item ---
if (!infoList.length && (item.topic || item.keywords)) {
  infoList.push({ topic: item.topic, keywords: item.keywords });
}

const topic = (infoList.find(i => i.topic)?.topic) || item.topic || '';

// --- Flatten keywords from all found blocks, parsing python-repr string if needed ---
let rawKeywords = [];
for (const info of infoList) {
  let kw = info.keywords;
  if (typeof kw === 'string') {
    try {
      kw = new Function('return ' + kw)();
    } catch (e) {
      continue; // skip unparsable block, don't kill whole run
    }
  }
  if (Array.isArray(kw)) rawKeywords.push(...kw);
}

// --- Number parsing helpers (Italian/European format) ---
function parseVolume(v) {
  if (v === undefined || v === null) return 0;
  const cleaned = String(v).trim().replace(/\./g, '').replace(/[^\d]/g, '');
  return cleaned ? parseInt(cleaned, 10) : 0;
}
function parseCpc(v) {
  if (v === undefined || v === null) return 0;
  let s = String(v).trim().replace(/[€\s]/g, '');
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : n;
}

// --- Normalize key for dedup: lowercase, strip accents, strip apostrophes, collapse spaces ---
function normalizeKey(str) {
  return String(str)
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/['']/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const fmtCpc = n => n.toFixed(2).replace('.', ',');

// --- Normalize + keep ALL keywords with non-empty text (volume 0 allowed) ---
// Also drop obvious junk entries that are URLs, not keywords
const normalized = rawKeywords
  .map(k => ({
    keyword: (k.keyword || '').trim(),
    search_volume: parseVolume(k.search_volume),
    cpc: parseCpc(k.cpc)
  }))
  .filter(k => k.keyword && !/^https?:\/\//i.test(k.keyword));

// --- Dedup: same normalized keyword -> keep highest-volume entry ---
const dedupMap = new Map();
for (const k of normalized) {
  const nk = normalizeKey(k.keyword);
  const existing = dedupMap.get(nk);
  if (!existing || k.search_volume > existing.search_volume) dedupMap.set(nk, k);
}
const validKeywords = Array.from(dedupMap.values());

// --- No keywords at all: fallback-ready blank shape ---
if (!validKeywords.length) {
  return [{
    json: {
      topic,
      needs_fallback: true,
      selected_keyword: '',
      keyword_volume: 0,
      keyword_cpc: '',
      article_topic: topic,
      selected_keywords_5: [],
      total_keywords_found: rawKeywords.length,
      total_valid_keywords: 0,
      duplicates_removed: 0,
      top_keywords: [],
      keyword_1: null,
      keyword_2: null,
      keyword_3: null,
      keyword_4: null,
      keyword_5: null
    }
  }];
}

// --- Sort strictly by search_volume desc, take top 5 regardless of volume ---
validKeywords.sort((a, b) => b.search_volume - a.search_volume);
const top5 = validKeywords.slice(0, 5);
const best = top5[0];
const top5Formatted = top5.map(k => ({
  keyword: k.keyword,
  search_volume: k.search_volume,
  cpc: fmtCpc(k.cpc)
}));

return [{
  json: {
    topic,
    needs_fallback: false,
    selected_keyword: best.keyword,
    keyword_volume: best.search_volume,
    keyword_cpc: fmtCpc(best.cpc),
    article_topic: best.keyword,
    selected_keywords_5: top5.map(k => k.keyword),
    total_keywords_found: rawKeywords.length,
    total_valid_keywords: validKeywords.length,
    duplicates_removed: normalized.length - validKeywords.length,
    top_keywords: top5Formatted,
    keyword_1: top5Formatted[0] || null,
    keyword_2: top5Formatted[1] || null,
    keyword_3: top5Formatted[2] || null,
    keyword_4: top5Formatted[3] || null,
    keyword_5: top5Formatted[4] || null
  }
}];

