let finalArticleContent = data.final_content || data.article_content || '';
finalArticleContent = finalArticleContent.replace(/contratti a termine/g, 'futuro');

// ✅ ২. <h1> খুঁজে টাইটেল বের করা
const h1Match = finalArticleContent.match(/<h1[^>]*>(.*?)<\/h1>/i);
const extractedTitle = h1Match ? h1Match[1].trim() : 'Articolo senza titolo';

// ✅ ৩. Slug তৈরি করা
