  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 80) || 'articolo-senza-slug';

// ✅ ৪. মেটা ডেটা সেট করা
const metaTitle = extractedTitle; 

