    plainText = plainText.substring(extractedTitle.length).trim();
}

const metaDescription = plainText.substring(0, 155) + (plainText.length > 155 ? '...' : '');
const finalMetaDescription = metaDescription.length > 20 ? metaDescription : "Tutte le informazioni su diritti, tutele e responsabilità dopo un infortunio sul lavoro.";

// ✅ ৬. পোস্ট বডি তৈরি
const postBody = {
  title: extractedTitle,       
  content: finalArticleContent, // ক্লিন করা কনটেন্ট
  status: 'draft',
  slug: cleanSlug,              
  excerpt: finalMetaDescription,
  meta: {
    _yoast_wpseo_title: metaTitle,
    _yoast_wpseo_metadesc: finalMetaDescription,
    rank_math_title: metaTitle,
    rank_math_description: finalMetaDescription,
    _seo_automation_keyword: data.selected_keyword || '',
    _seo_automation_date: new Date().toISOString()
  }
};

if (data.featured_image_id) {
  postBody.featured_media = data.featured_image_id;
}

return [{
  json: {
    post_body_json: JSON.stringify(postBody),
    article_title: extractedTitle,
    meta_title: metaTitle,
    meta_description: finalMetaDescription,
    slug: cleanSlug,
    excerpt: finalMetaDescription
  }
}];

