const original = $('Process QA Review Result').first().json;
const humanized = $input.first().json;

let humanizedHtml = '';
try {
  let content = humanized.text || '';
  content = content.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  const parsed = JSON.parse(content);
  humanizedHtml = parsed.article_html || original.article_content;
} catch(e) {
  humanizedHtml = original.article_content;
}

return [{
  json: {
    ...original,
    article_content: humanizedHtml,
    humanization_applied: true
  }
}];

// Node: Identify English Words
const data = $input.first().json;
const content = data.article_content || '';

const plainText = content
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// FIXED: Removed Italian homographs (in, per, via, ai, come, data, iter,
// so, e.g., i.e., etc — these are also legitimate Italian words/abbrevs
// and were causing massive false positives). Kept only unambiguous anglicisms.
const englishWords = [
  // Genuine multi-char English function words with no Italian collision
  'the','and','for','with','from','have','will','can','should','would',
  'about','which','their','there','these','those','been','were','when',
  'what','your','you','our','because','however','therefore','also','into',
  'than','then','conclusion','click','learn','upon','within','without',
  'through','during','between','among','versus','aka','ASAP',

  // Business/Financial anglicisms (genuinely English in Italian text)
  'CEO','CFO','CTO','broker','trading','forex','marketing',
  'business','compliance','enforcement','default','deal',
  'equity','bond','share','dividend','option','future','swap',
  'hedge','fund','portfolio','asset','liability','leverage',
  'spread','liquidity','volatility','arbitrage','settlement',
  'clearing','custody','withdrawal','advisory','consulting',
  'insight','solution','platform','framework',

  // Common English verbs unlikely to appear as Italian words
  'just','like','know','think','feel','need','give','take'
];

const allText = [
  plainText, data.title || '', data.meta_title || '',
  data.meta_description || '', data.h1 || '', data.excerpt || ''
].join(' ').toLowerCase();

const foundEnglish = [];
for (const word of englishWords) {
  const regex = new RegExp(`\\b${word}\\b`, 'gi');
  let match;
  while ((match = regex.exec(allText)) !== null) {
    foundEnglish.push({ word: match[0], lower: match[0].toLowerCase() });
  }
}

const uniqueWords = [...new Set(foundEnglish.map(w => w.lower))];

if (uniqueWords.length > 0) {
  const wordMap = {
    'broker':'intermediario','trading':'operazioni finanziarie','forex':'cambi valutari',
    'marketing':'promozione','business':'attività','compliance':'conformità normativa',
    'enforcement':'applicazione delle norme','default':'inadempimento','deal':'accordo',
    'equity':'capitale proprio','bond':'obbligazione','share':'quota','dividend':'dividendo',
    'option':'opzione','future':'contratti a termine','swap':'contratti di scambio',
    'hedge':'copertura','fund':'fondo','portfolio':'portafoglio','asset':'patrimonio',
    'liability':'passività','leverage':'leva','spread':'differenziale',
    'liquidity':'liquidità','volatility':'volatilità','arbitrage':'arbitraggio',
    'settlement':'regolamento','clearing':'compensazione','custody':'custodia',
    'withdrawal':'prelievo','advisory':'consulenza','consulting':'consulenza',
    'insight':'analisi','solution':'soluzione','platform':'piattaforma','framework':'quadro'
  };

  const translationMap = {};
  for (const w of uniqueWords) {
    // FIXED: skip words with no real mapping instead of injecting a fake
    // placeholder string into the prompt — that was the second bug causing
    // GPT to silently ignore unmapped words.
    if (wordMap[w]) translationMap[w] = wordMap[w];
  }

  return [{
    json: {
      ...data,
      english_words_found: true,
      english_words_list: Object.keys(translationMap),
      english_words_count: Object.keys(translationMap).length,
      english_translation_map: translationMap,
      english_words_detected_at: new Date().toISOString(),
      original_article_content: data.article_content,
      needs_english_fix: Object.keys(translationMap).length > 0
    }
  }];
}

return [{
  json: {
    ...data,
    english_words_found: false,
    english_words_count: 0,
    needs_english_fix: false,
    english_check_timestamp: new Date().toISOString()
  }
}];

// Node: Verify English Removed
const data = $input.first().json;

let fixedContent = data.article_content || data.article_html || data.text || '';

if (!fixedContent && data.text) {
  fixedContent = data.text;
