  'just','like','know','think','feel','need','give','take'
];

const allText = [
  plainText,
  data.title || '',
  data.meta_title || '',
  data.meta_description || '',
  data.h1 || '',
  data.excerpt || ''
].join(' ').toLowerCase();

const remainingEnglish = englishWords.filter(word => {
  const regex = new RegExp(`\\b${word}\\b`, 'gi');
  return regex.test(allText);
});

const uniqueRemaining = [...new Set(remainingEnglish)];

if (uniqueRemaining.length > 0) {
  return [{
    json: {
      ...data,
      article_content: fixedContent,
      article_html: fixedContent,
      english_verification_passed: false,
