      block_publication: true,
      error_message: `⚠️ ${uniqueRemaining.length} parole inglesi ancora presenti: ${uniqueRemaining.join(', ')}`,
      verification_timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    ...data,
    article_content: fixedContent,
    article_html: fixedContent,
    english_verification_passed: true,
    remaining_english_words: [],
    remaining_english_count: 0,
    block_publication: false,
    verification_timestamp: new Date().toISOString()
  }
}];

// ============================================================
