// ============================================================
// Extract Primary Keywords — RankMath multi-keyword aware,
// case + accent normalized, incomplete-fragment filtered,
// redundancy-cleaned, topic-relevant filtered (Italian stem-aware)
// NO relevant post found => return single empty placeholder item
// ============================================================

const items = $input.all();
let posts = [];

const stopwords = new Set([
  'il','lo','la','i','gli','le','un','uno','una','di','a','da','in','con',
  'su','per','tra','fra','e','o','ma','che','del','della','dei','delle',
  'dell','al','allo','alla','ai','agli','alle','come','cosa','quando',
  'dove','perche','perché','chi','cos','è','sono','se','non','più','puo','può'
]);

const incompleteEndings = new Set([
  'in','di','per','con','da','a','e','il','lo','la','un','uno','una',
  'al','allo','alla','ai','agli','alle','del','dello','della','dei','delle',
  'tra','fra','su','che','come'
]);

function decodeEntities(str) {
  return (str || '')
    .replace(/&#8217;/g, "'")
    .replace(/&#8211;/g, "-")
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"');
}

function normalizeKeyword(kw) {
  return (kw || '')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

// Crude Italian stemmer: strips plural/gender endings so
// "sinistri" ~ "sinistro", "stradali" ~ "stradale" match.
function italianStem(word) {
  if (!word || word.length < 4) return word;
  return word
    .replace(/(zioni|zione|mente)$/, '')
    .replace(/(issimo|issima)$/, '')
    .replace(/[oiae]$/, '');
}

function isValidKeyword(kw) {
  const words = kw.split(' ').filter(w => w.length > 0);
  if (words.length < 2) return false;
  const lastWord = words[words.length - 1];
  return !incompleteEndings.has(lastWord);
}

function deriveKeyword(title) {
  const clean = decodeEntities(title)
    .toLowerCase()
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .split(/\s+/)
    .filter(w => w.length > 2 && !stopwords.has(w));
  return clean.slice(0, 4).join(' ').trim();
}

function removeRedundantSubstrings(keywords) {
  const sorted = [...keywords].sort((a, b) => b.length - a.length);
  const result = [];
  for (const kw of sorted) {
    const isSubstring = result.some(existing => existing.includes(kw));
    if (!isSubstring) result.push(kw);
  }
  return result;
}

// --- Build posts array ---
for (const item of items) {
  const j = item.json;
  if (!j || !j.id) continue;

  const rawTitle = (j.title && typeof j.title.rendered === 'string') ? j.title.rendered : '';
  if (!rawTitle) continue;

  const title = decodeEntities(rawTitle);
  const link = j.link || '';
  const slug = j.slug || '';

  const focusKeywordRaw = (typeof j.focus_keyword === 'string') ? j.focus_keyword.trim() : '';

  let keywordList = focusKeywordRaw
    .split(',')
    .map(k => normalizeKeyword(k))
    .filter(k => k.length > 0 && isValidKeyword(k));

  if (keywordList.length === 0) {
    const derived = deriveKeyword(title);
    if (derived) keywordList = [derived];
  }

  const searchWords = normalizeKeyword(title + ' ' + focusKeywordRaw)
    .split(/\s+/)
    .filter(w => w.length > 2);
  const stemmedSearchWords = new Set(searchWords.map(italianStem));

  posts.push({
    id: j.id,
    title,
    link,
    slug,
    focus_keyword: focusKeywordRaw,
    keyword_list: keywordList,
    primary_keyword: keywordList[0] || '',
    source: focusKeywordRaw ? 'rankmath' : 'derived',
    _stemmedSearchWords: stemmedSearchWords // internal only, stripped before output
  });
}

// --- Topic-relevant filtering (accent + stem insensitive) ---
let currentTopic = '';
try {
  currentTopic = $('Find Pending1').first().json.Topic || '';
} catch (e) {
  currentTopic = '';
}

const topicWords = normalizeKeyword(currentTopic)
  .split(' ')
  .filter(w => w.length > 2);
const stemmedTopicWords = topicWords.map(italianStem);

// Case A: no topic at all (upstream node/field missing) -> keep OLD behavior,
// treat as "no filter", pass all posts through (this is NOT the empty-match case).
if (stemmedTopicWords.length === 0) {
  const rawExcluded = [...new Set(
    posts.flatMap(p => p.keyword_list).filter(kw => kw && kw.length > 0)
  )];
  const excludedKeywords = removeRedundantSubstrings(rawExcluded);

  return posts.map(p => {
    const { _stemmedSearchWords, ...clean } = p;
    return {
      json: {
        ...clean,
        current_topic: currentTopic,
        topic_words_used: topicWords,
        topic_match_mode: 'no_topic',
        topic_match_count: posts.length,
        excluded_keywords: excludedKeywords,
        excluded_keywords_csv: excludedKeywords.join(', '),
        is_topic_related: false
      }
    };
  });
}

// Case B: topic exists, filter by stem match against existing posts
const relevantPosts = posts.filter(p =>
  stemmedTopicWords.some(tw => p._stemmedSearchWords.has(tw))
);

// Case C: topic exists but genuinely ZERO relevant posts found
// -> do NOT fall back to all posts (that poisons excluded_keywords).
// -> return one lightweight placeholder item so downstream node doesn't break.
if (relevantPosts.length === 0) {
  return [{
    json: {
      id: null,
      title: '',
      link: '',
      slug: '',
      focus_keyword: '',
      keyword_list: [],
      primary_keyword: '',
      source: 'none',
      current_topic: currentTopic,
      topic_words_used: topicWords,
      topic_match_mode: 'no_relevant_posts',
      topic_match_count: 0,
      excluded_keywords: [],
      excluded_keywords_csv: '',
      is_topic_related: false
    }
  }];
}

// Case D: normal path — genuine relevant posts found
const rawExcluded = [...new Set(
  relevantPosts.flatMap(p => p.keyword_list).filter(kw => kw && kw.length > 0)
)];
const excludedKeywords = removeRedundantSubstrings(rawExcluded);

return relevantPosts.map(p => {
  const { _stemmedSearchWords, ...clean } = p;
  return {
    json: {
      ...clean,
      current_topic: currentTopic,
      topic_words_used: topicWords,
      topic_match_mode: 'stem',
      topic_match_count: relevantPosts.length,
      excluded_keywords: excludedKeywords,
      excluded_keywords_csv: excludedKeywords.join(', '),
      is_topic_related: true
    }
  };
});

