const allPosts = $input.all() || [];

let topic = '';
let keywords = [];
let topicSource = 'none';

try {
  const selectBest = $('Select Best Legal Keyword1').first().json;
  if (selectBest && !selectBest.error) {
    topic = selectBest.topic || selectBest.selected_keyword || '';
    keywords = selectBest.top_keywords || [];
    topicSource = 'Select Best Legal Keyword1';
  }
} catch (e) {}

if (!topic) {
  try {
    const webhookData = $('Webhook1').first().json;
    if (webhookData.body && webhookData.body.topic) {
      topic = webhookData.body.topic;
      topicSource = 'Webhook1 fallback';
    }
  } catch (e) {}
}

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/['']/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function stripHtml(html) {
  return String(html || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

if (!topic) {
  return [{
    json: {
      error: 'No topic found',
      debug: { topicSource, totalPostsReceived: allPosts.length },
      related_posts: [],
      related_posts_count: 0,
      all_posts: [],
      total_posts: allPosts.length,
      existing_posts: [],
      existing_posts_count: 0,
      existing_posts_text: 'Nessun articolo esistente trovato sul sito su questo argomento.',
      debug_match_log: []
    }
  }];
}

const normTopic = normalize(topic);
const topicCore = normTopic.split(' ')[0]; // e.g. "malasanita"

// Keyword গুলো থেকে শুধু ওগুলোই রাখো যেগুলোর মধ্যে topicCore আছে
const keywordListRaw = keywords
  .map(k => normalize(k.keyword || k || ''))
  .filter(kw => kw && kw.includes(topicCore));

const searchTerms = Array.from(new Set([normTopic, topicCore, ...keywordListRaw]))
  .filter(t => t.length > 4);

console.log('Topic:', topic, '| Source:', topicSource);
console.log('Search terms (restricted):', searchTerms);
console.log('Total posts received:', allPosts.length);

function getSearchableText(post) {
  if (!post || !post.json) return '';
  const j = post.json;
  const title = j.title && j.title.rendered ? j.title.rendered : (j.title || '');
  const excerpt = j.excerpt && j.excerpt.rendered ? j.excerpt.rendered : (j.excerpt || '');
  // content বাদ — শুধু title + excerpt (boilerplate-free, post-specific)
  return normalize(stripHtml(title) + ' ' + stripHtml(excerpt));
}

function matchedTerm(post) {
  const text = getSearchableText(post);
  if (!text) return null;
  for (const term of searchTerms) {
    if (text.includes(term)) return term;
  }
  return null;
}

