const allPostsList = [];
const debugMatches = [];

for (const post of allPosts) {
  if (post.json && post.json.id) {
    const j = post.json;
    const postObj = {
      id: j.id,
      title: j.title && j.title.rendered ? j.title.rendered : (j.title || ''),
      link: j.link || '',
      slug: j.slug || '',
      date: j.date || '',
      excerpt: stripHtml(j.excerpt && j.excerpt.rendered ? j.excerpt.rendered : (j.excerpt || '')).substring(0, 200),
      status: j.status || 'publish'
    };
    allPostsList.push(postObj);

    const match = matchedTerm(post);
    debugMatches.push({ id: j.id, title: postObj.title.substring(0, 60), matched: match });

    if (match) relatedPosts.push(postObj);
  }
}

console.log('Related posts found:', relatedPosts.length, '/', allPostsList.length);

// --- existing_posts_text: matched posts full details, LLM-friendly format ---
let existingPostsText;
if (relatedPosts.length > 0) {
  existingPostsText = relatedPosts
    .map((p, i) => {
      const lines = [
        `${i + 1}. Titolo: "${p.title}"`,
        `   URL: ${p.link}`
      ];
      if (p.slug) lines.push(`   Slug: ${p.slug}`);
      if (p.excerpt) lines.push(`   Estratto: ${p.excerpt}`);
      if (p.date) lines.push(`   Data pubblicazione: ${p.date}`);
      lines.push(`   Stato: ${p.status}`);
      return lines.join('\n');
    })
    .join('\n\n');
} else {
  existingPostsText = 'Nessun articolo esistente trovato sul sito su questo argomento.';
}

return [{
  json: {
    topic,
    topicSource,
    search_terms_used: searchTerms,
    selected_keyword: keywords.length > 0 ? (keywords[0].keyword || keywords[0] || '') : topic,
    selected_keywords_5: keywords.slice(0, 5).map(k => k.keyword || k || ''),
    all_keywords: keywords,
    related_posts: relatedPosts,
    related_posts_count: relatedPosts.length,
    all_posts: allPostsList,
    total_posts: allPostsList.length,
    existing_posts: relatedPosts,
    existing_posts_count: relatedPosts.length,
    existing_posts_text: existingPostsText,
    debug_match_log: debugMatches
  }
}];

const rows = $input.all();
const pending = rows.find(row => (row.json.Status || '').trim() === 'Pending');
if (pending) {
  return [{ json: { found: true, ...pending.json } }];
}
return [{ json: { found: false } }];

const output = $input.first().json.output;

return [
  {
    json: output
  }
];
